INSERT INTO `product` VALUES (1,1,1,'Giày Thể Thao Full Đen Tăng Chiều Cao Nam','Siêu nhẹ, êm chân, đế chống trơn trượt. Màu sắc trẻ trung, dễ phối đồ, thích hợp mang cặp, nhóm, lớ. Thích hợp mang đi chơi, đi dạo, tập gym, thể thao, chạy bộ. Nam nữ đều mang được. Giày Sneaker Nam Đế…','Kích cỡ',NULL,NULL,'2026-10-21 13:08:05','2026-10-21 13:08:05'),(2,1,NULL,'Giày sneaker thể thao nam thời trang buộc dây siêu nhẹ 266','Giày sneaker thể thao nam thời trang buộc dây siêu nhẹ 266Size 39 phù hợp chiều dài Giày dép là 24.5 cm. Size 40 phù hợp chiều dài Giày dép là 25.0 cm. Size 41 phù hợp chiều dài Giày dép là 25.5 cm. Size…','Kích cỡ',NULL,NULL,'2026-10-21 13:08:05','2026-10-21 13:08:05'),(3,1,2,'Giày thể thao nam sneaker đế cao tăng chiều cao hàng nhập siêu thoáng khí, da mềm mịn nhẹ siêu hót','=> Hàng hót mới về => Siêu phẩm giày thể thao cực chất với số lượng có hạn️Trời ơi hàng hót mới về lên dáng cực đẹp mà còn được khuyến mãi giảm giá tới 50% !- Thiết kế cực đỉnh, cực thoáng khí…','Kích cỡ',NULL,NULL,'2026-10-21 13:08:05','2026-10-21 13:08:05'),(4,1,NULL,'Giày nam tăng chiều cao, giầy Sneaker nam phong cách HOT TREND AVI - 416','I. THÔNG TIN SẢN PHẨM– Chất liệu: tổng hợp– Chất liệu đế: Cao su nguyên chất– Màu sắc: đen– Size: 39 - 44– Form giày ôm chân, thiết kế trẻ trung, hiện đạiII. TÍNH NĂNG– Chất liệu tổng hợp êm…','Kích cỡ',NULL,NULL,'2026-10-21 13:08:05','2026-10-21 13:08:05'),(5,1,NULL,'Giày Thể Thao Nam Sneaker - Giày Vải Nam Cao Cấp Nhẹ Bền Êm Chân','Thông Tin Sản Phẩm :- Chất liệu mặt trong : Vải khử mùi- Chất liệu mặt ngoài : Vải polyester chống thấm (vải gió)- Chất liệu đế : Cao su non đúc- Size : Đủ size dành cho nam- Mã sản phẩm : 9198…','Kích cỡ',NULL,NULL,'2026-10-21 13:08:05','2026-10-21 13:08:05'),(6,1,NULL,'Giày Nam, Giày Sneaker Nam, Chất Liệu Vải polyester (gió) chống thấm, Không Phai Màu NEW 2022','Thông Tin Sản Phẩm :- Chất liệu mặt trong : Vải khử mùi- Chất liệu mặt ngoài : Vải polyester chống thấm (vải gió)- Chất liệu đế : Cao su non đúc- S